command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "118b92c77c5ca8a78207b5236c42fa688796d108") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "b04119082799dc8e064ae3bd696f1e18fb76f085") { throw "candidate branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "b04119082799dc8e064ae3bd696f1e18fb76f085") { throw "candidate mismatch" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 20500 --configuration Release --browse-over-complete-model
if ($LASTEXITCODE -ne 0) { throw "indexed name sort/filter over-20k acceptance failed" }
$source = "C:\dev\flyExplorer\logs\m23\large-name-index-over-20k-after.png"
$target = "C:\dev\flyExplorer\logs\remote-evidence"
if (!(Test-Path -LiteralPath $source -PathType Leaf)) { throw "indexed visual evidence image missing" }
New-Item -ItemType Directory -Force -Path $target | Out-Null
Get-ChildItem -LiteralPath $target -File -ErrorAction SilentlyContinue | Remove-Item -Force
Copy-Item -LiteralPath $source -Destination (Join-Path $target "large-name-index-over-20k-after.png")
Get-FileHash -Algorithm SHA256 -LiteralPath $source | ForEach-Object { "$($_.Path) $($_.Hash)" } | Set-Content -Encoding UTF8 -LiteralPath (Join-Path $target "large-name-index-sha256.txt")
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_NAME_INDEX_ACCEPTANCE_PASS"
